<?php require_once 'config.php'; if(!current_user())redirect('login.php');$pageTitle='My account';$orders=[];try{$stmt=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$stmt->execute([current_user()['id']]);$orders=$stmt->fetchAll();}catch(Throwable $e){}include 'includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="eyebrow">Your farm account</div><h1>Welcome,<br><?= e(explode(' ',current_user()['full_name'])[0]) ?>.</h1><p>Keep track of your orders and the next good thing headed your way.</p><a class="btn btn-outline" href="logout.php">Sign out</a></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Order history</div><h2>Your orders.</h2></div><a class="btn btn-primary" href="shop.php">Shop the farm</a></div><?php if(!$orders): ?><div class="notice">No orders yet. Your first farm delivery is just a few clicks away.</div><?php else: ?><table class="cart-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td>#<?= (int)$order['id'] ?></td><td><?= e(date('d M Y',strtotime($order['created_at']))) ?></td><td>KSh <?= number_format((float)$order['total']) ?></td><td><?= e(ucfirst($order['status'])) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section><?php include 'includes/footer.php'; ?>
